// Differential runner: compares the Python executable against a Node entry file.
// Usage: node diff.mjs <entry.mjs> [--limit N] [--tag PREFIX] [--stderr] [--out report.json]
import { readFileSync, writeFileSync } from 'node:fs';
import { spawn } from 'node:child_process';

const EXE = '/workspace/dataset/test6_executable';
const argv = process.argv.slice(2);
const entry = argv[0];
if (!entry) { console.error('usage: node diff.mjs <entry.mjs> [opts]'); process.exit(64); }
const getOpt = (n, d) => { const i = argv.indexOf(n); return i >= 0 ? argv[i + 1] : d; };
const limit = Number(getOpt('--limit', '0')) || 0;
const tagFilter = getOpt('--tag', '');
const cmpStderr = argv.includes('--stderr');
const outPath = getOpt('--out', '');
const CONC = Number(getOpt('--conc', '48'));

let cases = readFileSync('/tmp/dt/corpus.jsonl', 'utf8').trim().split('\n').map((l) => JSON.parse(l));
if (tagFilter) cases = cases.filter((c) => c.tag.startsWith(tagFilter));
if (limit) cases = cases.slice(0, limit);

function run(cmd, args) {
  return new Promise((resolve) => {
    const p = spawn(cmd, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let so = '', se = '';
    p.stdout.on('data', (d) => { so += d; });
    p.stderr.on('data', (d) => { se += d; });
    p.on('error', (e) => resolve({ rc: -1, so: '', se: String(e) }));
    p.on('close', (rc) => resolve({ rc, so, se }));
  });
}

// Normalize stderr so PyInstaller PID noise / prog name / file paths don't create false diffs.
function normErr(s) {
  return s
    .replace(/\[PYI-\d+:ERROR\][^\n]*\n?/g, '')
    .replace(/test6(_executable|\.py|\.mjs)/g, 'PROG')
    .trim();
}

const mismatches = [];
let done = 0, ok = 0;
let idx = 0;

async function worker() {
  while (idx < cases.length) {
    const i = idx++;
    const c = cases[i];
    const [a, b] = await Promise.all([run(EXE, c.argv), run(process.execPath, [entry, ...c.argv])]);
    let bad = null;
    if (a.so !== b.so) bad = 'stdout';
    else if (a.rc !== b.rc) bad = 'rc';
    else if (cmpStderr && normErr(a.se) !== normErr(b.se)) bad = 'stderr';
    done++;
    if (bad) {
      mismatches.push({ i, tag: c.tag, argv: c.argv, kind: bad, py: { rc: a.rc, so: a.so, se: normErr(a.se) }, js: { rc: b.rc, so: b.so, se: normErr(b.se) } });
    } else ok++;
    if (done % 2000 === 0) process.stderr.write(`  ...${done}/${cases.length} (${mismatches.length} bad)\n`);
  }
}

const t0 = process.hrtime.bigint === undefined ? 0 : 0;
await Promise.all(Array.from({ length: CONC }, worker));

console.log(`total=${cases.length} pass=${ok} fail=${mismatches.length}`);
const byTag = {};
for (const m of mismatches) byTag[m.tag] = (byTag[m.tag] || 0) + 1;
if (mismatches.length) console.log('failures by tag:', JSON.stringify(byTag));
for (const m of mismatches.slice(0, 60)) {
  console.log(`FAIL[${m.kind}] ${m.tag} argv=${JSON.stringify(m.argv)}\n   py rc=${m.py.rc} out=${JSON.stringify(m.py.so)}${cmpStderr ? ' err=' + JSON.stringify(m.py.se) : ''}\n   js rc=${m.js.rc} out=${JSON.stringify(m.js.so)}${cmpStderr ? ' err=' + JSON.stringify(m.js.se) : ''}`);
}
if (mismatches.length > 60) console.log(`... and ${mismatches.length - 60} more`);
if (outPath) writeFileSync(outPath, JSON.stringify(mismatches, null, 1));
process.exit(mismatches.length ? 1 : 0);

