// Appends newly-discovered edge cases (unicode ws/digits, NaN sign, __str__ leftdigits
// boundary, repr decpt 16/17 boundary) to the differential corpus.
import { appendFileSync, readFileSync } from 'node:fs';

const cases = [];
const add = (argv, tag) => cases.push({ argv, tag });

// --- unicode whitespace accepted by Python float() ------------------------
const WS = ['	', '
', '', ' ', '', ' ', '', ' ',
  ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ', ' ', ' ', ' ', '　'];
for (const w of WS) {
  add([`--amount=${w}5`, '--currency', 'USD'], 'I:ws');
  add([`--amount=5${w}`, '--currency', 'USD'], 'I:ws');
  add([`--amount=${w}5.5${w}`, '--currency', 'USD'], 'I:ws');
  add([`--amount=5${w}5`, '--currency', 'USD'], 'I:ws');   // interior -> reject
}
// non-whitespace look-alikes -> must reject
for (const w of ['​', '‌', '⁠', '﻿', '᠎']) {
  add([`--amount=${w}5`, '--currency', 'USD'], 'I:wsfake');
}

// --- unicode Nd digits across many blocks --------------------------------
const ND0 = [0x0030, 0x0660, 0x06f0, 0x07c0, 0x0966, 0x09e6, 0x0a66, 0x0ae6, 0x0b66, 0x0be6,
  0x0c66, 0x0ce6, 0x0d66, 0x0de6, 0x0e50, 0x0ed0, 0x0f20, 0x1040, 0x1090, 0x17e0, 0x1810,
  0x1946, 0x19d0, 0x1a80, 0x1a90, 0x1b50, 0x1bb0, 0x1c40, 0x1c50, 0xa620, 0xa8d0, 0xa900,
  0xa9d0, 0xa9f0, 0xaa50, 0xabf0, 0xff10];
for (const base of ND0) {
  const d = (n) => String.fromCodePoint(base + n);
  add([`--amount=${d(5)}`, '--currency', 'USD'], 'I:nd');
  add([`--amount=${d(1)}${d(2)}${d(3)}`, '--currency', 'USD'], 'I:nd');
  add([`--amount=${d(7)}.${d(2)}${d(5)}`, '--currency', 'USD'], 'I:nd');   // ASCII dot
  add([`--amount=${d(1)}e${d(3)}`, '--currency', 'USD'], 'I:nd');
}
// astral-plane Nd
for (const cp of [0x104a0, 0x11066, 0x110f0, 0x1d7ce, 0x1d7f6, 0x1e950]) {
  const d = (n) => String.fromCodePoint(cp + n);
  add([`--amount=${d(4)}${d(2)}`, '--currency', 'USD'], 'I:ndastral');
  add([`--amount=${d(9)}.${d(5)}`, '--currency', 'USD'], 'I:ndastral');
}
// non-Nd numerics and non-ASCII separators -> must reject
for (const v of ['５．５', '5．5', '5。5', '½', '⁵', 'Ⅵ',
  '五', '〇', 'Ⅰ', '²', '⅔', '〡', 'ᛮ', '⊕', '5٫5',
  '5٠5', '５,５']) {
  add([`--amount=${v}`, '--currency', 'USD'], 'I:nonnd');
}

// --- NaN / Infinity sign handling ---------------------------------------
for (const v of ['-nan', '+nan', '-NaN', '-NAN', '-inf', '+inf', '-Infinity', '-infinity',
  '  -nan  ', '- nan']) {
  add([`--amount=${v}`, '--currency', 'USD'], 'I:nansign');
}

// --- Decimal.__str__ leftdigits > -6 boundary ---------------------------
for (const v of ['1e-4', '1e-5', '1e-6', '1e-7', '1e-8', '5e-6', '5e-7', '5e-8', '1.5e-6',
  '1.5e-5', '9.9e-7', '9.99e-7', '9.999999e-7', '1.000001e-6', '1.0000001e-5', '2e-6', '2e-7',
  '1e-9', '1.23456e-6', '1.23456e-5', '9.876e-8', '3e-6', '4e-7', '1.1e-6', '1.1e-5']) {
  add(['--amount', v, '--currency', 'USD'], 'I:leftdigits');
}

// --- repr decpt 16/17 fixed<->exponential boundary ----------------------
for (const v = 0; false;) { }
const B = [];
for (let k = 12; k <= 20; k++) {
  B.push('1e' + k, '9e' + k, '1.5e' + k, '9.999999999999999e' + k, '1.0000000000000002e' + k);
}
B.push('9999999999999998', '9999999999999999', '10000000000000000', '10000000000000002',
  '999999999999999', '1000000000000000', '1234567890123456', '12345678901234567',
  '123456789012345678', '99999999999999999999', '1234567890123456.7', '1e16', '1e17',
  '0.0001', '0.00012', '0.000100000000000000005', '1e-4', '9.999e-5');
for (const v of B) add(['--amount', v, '--currency', 'USD'], 'I:decpt');

// --- coefficients ending in 0 / 5 (trailing-zero-strip vs ideal_exp) ---
for (const v = 0; false;) { }
const C = [];
for (let k = 1; k <= 40; k++) {
  C.push('5e-' + k, '5e' + k, '2.5e-' + k, '25e' + k, '1' + '0'.repeat(Math.min(k, 25)),
    '0.' + '0'.repeat(Math.min(k, 20)) + '5');
}
for (const v of C) add(['--amount', v, '--currency', 'EUR'], 'I:coeff');

// --- underscore grammar exhaustive ------------------------------------
for (const v of ['1_000', '1_0.5', '1_000_000.000_1', '1e1_0', '1_2e3_4', '.5_5', '5_5.',
