// Dumps the Python executable's ground truth for the targeted I:* corpus cases.
import { readFileSync, writeFileSync } from 'node:fs';
import { spawn } from 'node:child_process';

const EXE = '/workspace/dataset/test6_executable';
const cases = readFileSync('/tmp/dt/corpus.jsonl', 'utf8').trim().split('\n')
  .map((l) => JSON.parse(l)).filter((c) => c.tag.startsWith('I:'));

const run = (args) => new Promise((res) => {
  const p = spawn(EXE, args, { stdio: ['ignore', 'pipe', 'pipe'] });
  let so = '', se = '';
  p.stdout.on('data', (d) => { so += d; });
  p.stderr.on('data', (d) => { se += d; });
  p.on('close', (rc) => res({ rc, so, se }));
});

const esc = (s) => JSON.stringify(s);
const hex = (s) => [...s].map((c) => c.codePointAt(0).toString(16).padStart(4, '0')).join(' ');

const out = [];
let i = 0;
async function worker() {
  while (i < cases.length) {
    const k = i++;
    const c = cases[k];
    const r = await run(c.argv);
    const amt = (c.argv.find((a) => a.startsWith('--amount')) || '').replace(/^--amount=?/, '');
    out[k] = `${c.tag}\t${esc(c.argv)}\tamountCP=[${hex(amt)}]\trc=${r.rc}\tout=${esc(r.so)}` +
      (r.rc === 2 ? `\terr=${esc((r.se.split('\n').pop() || r.se.trim().split('\n').pop()) || '')}` : '');
  }
}
await Promise.all(Array.from({ length: 40 }, worker));
writeFileSync('/tmp/dt/ground_truth_I.txt', out.join('\n') + '\n');

// summarise the two most interesting questions
const ws = cases.map((c, k) => ({ c, k })).filter((x) => x.c.tag === 'I:ws');
const accepted = [], rejected = [];
for (const { c, k } of ws) {
  const raw = c.argv[0].slice('--amount='.length);
  if (!/^\D?5$/u.test(raw) && raw.length !== 2) continue;   // only the leading-ws form
  const wsChar = raw.replace(/5/g, '');
  if (wsChar.length !== 1) continue;
  (out[k].includes('rc=0') ? accepted : rejected).push('U+' + wsChar.codePointAt(0).toString(16).toUpperCase().padStart(4, '0'));
}
console.log('leading-whitespace ACCEPTED:', accepted.join(' '));
console.log('leading-whitespace REJECTED:', rejected.join(' '));
const ndBad = cases.map((c, k) => ({ c, k })).filter((x) => x.c.tag.startsWith('I:nd') && out[x.k].includes('rc=2'));
console.log(`Nd cases rejected: ${ndBad.length}/${cases.filter((c) => c.tag.startsWith('I:nd')).length}`);
for (const { k } of ndBad.slice(0, 40)) console.log('  ', out[k]);
console.log('wrote /tmp/dt/ground_truth_I.txt');

